//[microTexture NCAs](https://www.shadertoy.com/view/slGGzD)

let shader1;
let u_time;

function setup() 
{
	createCanvas(1112, 834, WEBGL);
	shader1 = createShader(vertShader, fragShader);

	// fucking magic
	let gl = drawingContext;
	gl.blendFunc(gl.SRC_ALPHA, gl.ONE);
	gl.enable(gl.BLEND);
	//gl.disable(gl.DEPTH_TEST);

	u_time = 0;
}

function windowResized() 
{
	resizeCanvas(width, height);
}
/*
function mouseClicked()
{
	console.log(frameRate());
}
*/
function draw() 
{
	background(0);

	scale(max(width, height) / 2);
	rotateZ(PI);
	rotateX(PI / 4);
	rotateY(-PI / 4);

	resetShader();

	noStroke();
	shader(shader1);
	shader1.setUniform("u_time", u_time);

	for (let i = 0; i < 1; i += 1 / 1000.0) 
	{
		push();
		translate(0, 0, i - 0.5);
		shader1.setUniform("u_layer", i);
		plane(1, 1);
		pop();
	}

	u_time += deltaTime / 1000.0;
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed() {
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: vert ===
const vertShader = `
	//preprocessor macros
	#ifdef GL_ES
	precision mediump float;
	#endif

	// attributes, in
	attribute vec3 aPosition;

	// attributes, out
	varying vec3 vPosition;

	// matrices
	uniform mat4 uProjectionMatrix;
	uniform mat4 uModelViewMatrix;

	//user specified parameters
	uniform float u_layer;

	//per-vertex program
	void main() 
	{
		vec4 positionVec4 = vec4(aPosition, 1.0);
		gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;

		//vertex position for the fragment shader
		vPosition = aPosition + vec3(0.5, 0.5, u_layer);
	}
`;



// === Tab: shared ===

