	// Start of code Inigo Quilez
	float hash(vec3 p)  // replace this by something better
	{
			p  = fract( p*0.3183099+.1 );
		p *= 17.0;
			return fract( p.x*p.y*p.z*(p.x+p.y+p.z) );
	}

	float noise( in vec3 x )
	{
			vec3 i = floor(x);
			vec3 f = fract(x);
			f = f*f*(3.0-2.0*f);

			return mix(mix(mix( hash(i+vec3(0,0,0)), 
													hash(i+vec3(1,0,0)),f.x),
										 mix( hash(i+vec3(0,1,0)), 
													hash(i+vec3(1,1,0)),f.x),f.y),
								 mix(mix( hash(i+vec3(0,0,1)), 
													hash(i+vec3(1,0,1)),f.x),
										 mix( hash(i+vec3(0,1,1)), 
													hash(i+vec3(1,1,1)),f.x),f.y),f.z);
	}

	float octaveNoise(in vec2 realuv, in float time){
		float f = 0.0;

		//scale
		vec2 uv = realuv * 8.0;
		mat2 m = mat2( 1.6,  1.2, -1.2,  1.6 );
		f  = 0.7 * noise( vec3(uv, time*0.6)  ); 
		uv = m*uv;    
		f += 0.3 * noise( vec3(uv, time*0.2+100.)  ); 
		return 0.5 + 0.5*f;
	}
	// ---- End of code by Inigo Quilez
	`;

// === Tab: frag ===
const fragShader = `
	//preprocessor macros
	#ifdef GL_ES
	precision mediump float;
	#endif

	//attributes, in
	varying vec3 vPosition;

	//user specified parameters
	uniform float u_layer; //the plane we are currently rendering to
	uniform float u_time;

	`+shared+`

	void main() 
	{
		float f = octaveNoise(vPosition.xy * 1.0, vPosition.z * 16.0 + u_time);	

		if(f > 0.8) 
		{
			gl_FragColor = vec4(vPosition, 1.0);
		} else {
			gl_FragColor = vec4(0.0, 0.0, 0.0, mod(u_layer, 0.005));
		}
	}
`;

